/**
 * PM2 Ecosystem Configuration for Agent ${AGENT_ID} — Ghostfolio
 *
 * Auto-generated by `har env launch` — do not edit manually.
 * Customize .har/ecosystem.agent.template.cjs to change processes.
 *
 * The primary app is Ghostfolio, which runs as two dev processes:
 *   - api:    NestJS (`nx run api:serve --watch`) on API_PORT, inspector on DEBUG_PORT
 *   - client: Angular dev server (`nx run client:serve`) on FE_PORT, proxying
 *             /api, /assets and /admin/queues to this slot's API
 * PostgreSQL and Redis are shared infra (docker-compose.agent.yml).
 */

// Launch writes this file (and .env.agent.N) to the work dir root,
// so __dirname IS the work dir — repo root or the agent's git worktree.
const fs = require('fs');
const path = require('path');

const agentEnvPath = path.resolve(__dirname, '.env.agent.${AGENT_ID}');
const env = {};
try {
  for (const line of fs.readFileSync(agentEnvPath, 'utf8').split('\n')) {
    const m = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/);
    if (m && !line.trimStart().startsWith('#')) env[m[1]] = m[2].replace(/^["']|["']$/g, '');
  }
} catch {}

const apiPort = env.API_PORT || env.PORT;
const fePort = env.FE_PORT || '${FE_PORT}';
const debugPort = env.DEBUG_PORT || '${DEBUG_PORT}';

// The upstream apps/client/proxy.conf.json hardcodes the API on :3333. Write a
// per-slot copy pointing at this slot's API port. node_modules/ is gitignored,
// so the file never shows up as an untracked change in the session worktree.
const proxyConfigPath = path.join(__dirname, 'node_modules', '.cache', 'har', 'proxy.agent-${AGENT_ID}.json');
const apiTarget = { target: `http://localhost:${apiPort}`, secure: false };
fs.mkdirSync(path.dirname(proxyConfigPath), { recursive: true });
fs.writeFileSync(
  proxyConfigPath,
  JSON.stringify({ '/admin/queues': apiTarget, '/api': apiTarget, '/assets': apiTarget }, null, 2),
);

const nx = path.join(__dirname, 'node_modules', '.bin', 'nx');
const PATH = env.PATH || `${path.join(__dirname, 'node_modules', '.bin')}:${process.env.PATH}`;

const common = {
  interpreter: 'none',
  cwd: __dirname,
  watch: false,
  autorestart: true,
  kill_timeout: 5000,
  merge_logs: true,
  time: true,
};

module.exports = {
  apps: [
    {
      ...common,
      name: 'har-${HARNESS_PROJECT_NAME}-agent-${AGENT_ID}-api',
      script: 'bash',
      // Same as `npm run start:server`, plus a per-slot inspector port.
      args: ['-c', `"${nx}" run api:copy-assets && exec "${nx}" run api:serve --watch --port=${debugPort}`],
      env: {
        ...env,
        PATH,
        NODE_ENV: 'development',
        PORT: apiPort,
      },
    },
    {
      ...common,
      name: 'har-${HARNESS_PROJECT_NAME}-agent-${AGENT_ID}-client',
      script: 'bash',
      // Same as `npm run start:client`, made agent-friendly: plain HTTP instead
      // of the self-signed localhost cert, no HMR, no auto-opened browser.
      args: [
        '-c',
        `"${nx}" run client:copy-assets && exec "${nx}" run client:serve --configuration=development-en` +
          ` --host=localhost --port=${fePort} --ssl=false --hmr=false --proxy-config="${proxyConfigPath}"`,
      ],
      env: {
        ...env,
        PATH,
        NODE_ENV: 'development',
      },
    },
  ],
};
